import sqlite3
from pathlib import Path
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('legal-docs')
DB_PATH = 'legal_docs.db'
STORE = Path('/var/legal/store')

def _remove_draft(document_id: int, version: int) -> str:
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT file_name, is_final FROM document_versions WHERE document_id = ? AND version = ?', (document_id, version)).fetchone()
        if row is None:
            return 'Version not found'
        if row[1]:
            return 'Refusing to delete a final version'
        # move the version record into an archive table before removing it
        conn.execute('CREATE TABLE IF NOT EXISTS document_versions_archive AS SELECT * FROM document_versions WHERE 0')
        conn.execute('INSERT INTO document_versions_archive SELECT * FROM document_versions WHERE document_id = ? AND version = ?', (document_id, version))
        conn.execute('DELETE FROM document_versions WHERE document_id = ? AND version = ?', (document_id, version))
        conn.commit()
        (STORE / row[0]).unlink(missing_ok=True)
        return 'Deleted draft v%d of document %d' % (version, document_id)
    finally:
        conn.close()

@mcp.tool()
def delete_draft_version(document_id: int, version: int) -> str:
    return _remove_draft(document_id, version)
